import type { NextConfig } from 'next'

const nextConfig: NextConfig = {
  cacheComponents: true,
}

export default nextConfig

export type Post = {
  id: string
  title: string
  content: string
}

const posts: Post[] = []

export function getPostsFromDb(): Post[] {
  return posts
}

export function createPostInDb(title: string, content: string): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
  }
  posts.push(post)
  return post
}

import { cacheTag } from 'next/cache'
import { getPostsFromDb, type Post } from '@/lib/posts'

export async function getPosts(): Promise<Post[]> {
  'use cache'
  cacheTag('posts')
  return getPostsFromDb()
}

'use server'

import { updateTag } from 'next/cache'
import { createPostInDb } from '@/lib/posts'

export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '')
  const content = String(formData.get('content') ?? '')

  createPostInDb(title, content)
  updateTag('posts')
}

import { createPost } from '@/app/actions'
import { getPosts } from '@/lib/get-posts'

export default async function Home() {
  const posts = await getPosts()

  return (
    <main>
      <h1>Posts</h1>
      <form action={createPost}>
        <input name="title" placeholder="Title" required />
        <textarea name="content" placeholder="Content" required />
        <button type="submit">Create Post</button>
      </form>
      <ul>
        {posts.map((post) => (
          <li key={post.id}>
            <h2>{post.title}</h2>
            <p>{post.content}</p>
          </li>
        ))}
      </ul>
    </main>
  )
}
